B.alr=new A.aH(B.aiG,20,B.i,null,null)
B.H9=new A.aH(B.zf,null,null,null,null)
B.ajN=new A.aq(63594,"MaterialIcons",!1)
B.als=new A.aH(B.ajN,18,null,null,null)
B.aiD=new A.aq(57415,"MaterialIcons",!1)
B.Ha=new A.aH(B.aiD,null,null,null,null)
B.alt=new A.aH(B.Gl,56,B.a7,null,null)
B.alu=new A.aH(B.Gw,28,B.a7,null,null)
B.alw=new A.aa("Hesab\u0131nla kay\u0131tlar\u0131n g\xfcvenle saklan\u0131r ve diyetisyenin seni takip edebilir. Sa\u011fl\u0131k bilgilerin yaln\u0131zca sana ve diyetisyenine g\xf6r\xfcn\xfcr.",13.5,null)
B.aly=new A.aa("Ayn\u0131 kamp grubunda farkl\u0131 y\xf6relerden dan\u0131\u015fanlar var ve her birinin listesi kendi sofras\u0131na g\xf6re ayr\u0131 haz\u0131rlan\u0131r. Senin listende de bu yemekler yer al\u0131r; yasak yok, k\xfc\xe7\xfck dokunu\u015flar var.",13,null)
B.alz=new A.aa("Kaynak: DS\xd6, Bel \xe7evresi ve bel-kal\xe7a oran\u0131 uzman raporu (2011) \xb7 NICE, Obezite: tan\u0131mlama ve s\u0131n\u0131flama (2022, bel-boy oran\u0131) \xb7 ISAK antropometri ilkeleri",11.5,null)
B.alA=new A.aa("yak\u0131nda",11,null)
B.alB=new A.aa("Kat\u0131l\u0131mc\u0131 tarifidir; besin de\u011ferleri hesaplanmam\u0131\u015ft\u0131r. Ki\u015fisel porsiyonun onayl\u0131 plan\u0131ndad\u0131r.",12,null)
B.alD=new A.aa("Kaynaklar: EFSA yeti\u015fkin referans de\u011feri 0,83 g/kg; ISSN 2017 sporcu \xf6nerisi 1,4\u20132,0 g/kg. B\xf6brek hastal\u0131\u011f\u0131nda protein ihtiyac\u0131 farkl\u0131d\u0131r: bu de\u011ferleri kullanma, diyetisyenine dan\u0131\u015f.",12,null)
B.alE=new A.aa("Uygulamaya girece\u011fin sa\u011fl\u0131k bilgileri KVKK'ya g\xf6re \xf6zel nitelikli ki\u015fisel veridir. Bu y\xfczden a\xe7\u0131k r\u0131zan\u0131 istiyoruz. R\u0131zan\u0131 istedi\u011fin zaman Profil > Gizlilik b\xf6l\xfcm\xfcnden geri alabilir, verilerini indirebilir ya da silebilirsin.",15,null)
B.alF=new A.aa("\xd6l\xe7\xfcmlerin Dyt. Cansu'ya gider ve program\u0131n\u0131 buna g\xf6re de\u011ferlendirir.",12,null)
B.alG=new A.aa("De\u011ferler 100 g ba\u015f\u0131nad\u0131r. Bir besine dokun: istedi\u011fin gramda ne kadar protein ve lif oldu\u011funu g\xf6r.",12,null)
B.alH=new A.aa("Gebelik, emzirme, kronik hastal\u0131k ya da \xe7ocuk i\xe7in birebir destekte ilgili b\xf6l\xfcmdeki sorular\u0131 doldurman plan\u0131 daha h\u0131zl\u0131 haz\u0131rlar.",12,null)
B.alK=new A.aa("Kan tahlillerini Kamp > Kan tahlillerim b\xf6l\xfcm\xfcnden y\xfckleyebilirsin. \u0130la\xe7 dozunu kendi ba\u015f\u0131na de\u011fi\u015ftirme; beslenme plan\u0131n hekiminle uyumlu haz\u0131rlan\u0131r.",12,null)
B.alL=new A.aa("kcal de\u011ferleri MET tablosuna g\xf6re yakla\u015f\u0131k tahmindir; ki\u015fiden ki\u015fiye de\u011fi\u015fir.",11.5,null)
B.alM=new A.aa("Kaynak: USDA FoodData Central ve T\xfcrKomp de\u011ferleri, yuvarlanm\u0131\u015f. Pi\u015firme ve markaya g\xf6re de\u011fi\u015fir.",11,null)
B.Hb=new A.aa("Horlama, uykuda nefesin durmas\u0131, sabah ba\u015f a\u011fr\u0131s\u0131 ya da g\xfcn i\xe7inde s\xfcrekli uyuklama varsa hekimine dan\u0131\u015f; uyku apnesi kilo vermeyi zorla\u015ft\u0131rabilir ve tedavi edilebilir.",12,null)
B.alN=new A.aa("Bu ay hangi hizmeti almak istersin? Se\xe7imini Dyt. Cansu g\xf6r\xfcr ve sana uygun zaman\u0131 birlikte planlars\u0131n\u0131z.",13,null)
B.alO=new A.aa("A\u011fr\u0131, ba\u015f d\xf6nmesi ya da nefes darl\u0131\u011f\u0131 hissedersen dur.",12,null)
B.alP=new A.aa("18 ya\u015f alt\u0131 dan\u0131\u015fanlar i\xe7in g\xf6r\xfc\u015fmeler ebeveyn ya da yasal vasi onay\u0131 ve kat\u0131l\u0131m\u0131yla yap\u0131l\u0131r.",12,null)
B.alQ=new A.aa("Hen\xfcz tahlil g\xf6ndermedin.",13,null)
B.alR=new A.aa("En az 3/5 al\u0131\u015fkanl\u0131kla ge\xe7en her g\xfcn seriyi b\xfcy\xfct\xfcr. Esnek seri: 7 g\xfcnde bir bo\u015f g\xfcn seriyi bozmaz, \xe7\xfcnk\xfc hayat bazen yorar.",12.5,null)
B.alS=new A.aa("DS\xd6: haftada 150\u2013300 dk orta yo\u011funluk + 2 g\xfcn kas g\xfc\xe7lendirme",12,null)
B.alT=new A.aa("Yeni bir plan ya da kalori hedefi otomatik olu\u015fturulmaz; de\u011fi\u015fiklikleri uzman yapar.",11.5,null)
B.alV=new A.aa("Hareket \xf6nerileri genel bilgilendirmedir, t\u0131bbi tedavi yerine ge\xe7mez. A\u011fr\u0131, ba\u015f d\xf6nmesi ya da nefes darl\u0131\u011f\u0131nda dur.",12,null)
B.alW=new A.aa("Onaylanan tarifler burada g\xf6r\xfcn\xfcr. \u0130lk payla\u015fan sen olabilirsin.",13,null)
B.alX=new A.aa("Programdan farkl\u0131 bir \u015fey yediysen sorun de\u011fil, oldu\u011fu gibi yaz.",12,null)
B.alY=new A.aa("Not: Veli onay\u0131n\u0131n nas\u0131l al\u0131naca\u011f\u0131 ve do\u011frulanaca\u011f\u0131 (imza, kimlik do\u011frulama, gencin kendi verisine eri\u015fimi) hukuki inceleme gerektirir. Bu ak\u0131\u015f \u015fimdilik tasar\u0131m tasla\u011f\u0131d\u0131r.",12,null)
B.alZ=new A.aa("Hen\xfcz antrenman yok. Sa\u011f alttaki d\xfc\u011fmeyle ilkini ekle.",13,null)
B.am_=new A.aa("yak\u0131nda burada",12,null)
B.am0=new A.aa("Merak etti\u011fin besini yaz ya da foto\u011fraf\u0131n\u0131 \xe7ek. Karbonhidrat, protein, ya\u011f ve lif miktar\u0131n\u0131 hesaplayal\u0131m. Bu hesap kaydedilmez, \xf6\u011f\xfcn olarak g\xf6nderilmez.",13,null)
B.am1=new A.aa("Dyt. Cansu \xd6zdal",11,null)
B.am2=new A.aa("Bu sayfa genel bilgilendirmedir. Porsiyonlar\u0131n ve sana \xf6zel liste Dyt. Cansu'nun onay\u0131yla gelir.",12,null)
B.am3=new A.aa("Bu bilgiler sa\u011fl\u0131k verisidir. Yaln\u0131zca sen \"G\xf6nder\"e bast\u0131\u011f\u0131nda, senin WhatsApp'\u0131ndan Dyt. Cansu'ya gider; uygulama ba\u015fka kimseyle payla\u015fmaz.",12,null)
B.am4=new A.aa("Ki\u015fisel listen kendi mutfa\u011f\u0131na g\xf6re haz\u0131rlan\u0131r: ayn\u0131 grupta olsan da sofran sana \xf6zel.",13,null)
B.am5=new A.aa("Tart\u0131 sonucunu ve bel, kal\xe7a, g\xf6bek, g\xf6\u011f\xfcs \xf6l\xe7\xfclerini gir.",13,null)
B.am6=new A.aa("Sadece payla\u015fmak istediklerini i\u015faretle. Bu bilgiler hareket \xf6nerilerini ve su hedefini g\xfcvenli tutmak i\xe7in kullan\u0131l\u0131r.",13,null)
B.ama=new A.aa("Bitkisel kaynaklar (baklagil, tam tah\u0131l, kuruyemi\u015f) protein yan\u0131nda lif de getirir; hayvansal kaynaklarla d\xf6n\xfc\u015f\xfcml\xfc kullanmak en dengeli yoldur.",12,null)
B.amb=new A.aa("\u0130kinci \xf6l\xe7\xfcm\xfcn\xfc girdi\u011finde de\u011fi\u015fimin burada g\xf6r\xfcnecek.",13,null)
B.amc=new A.aa("G\xf6rsel: free-exercise-db (kamu mal\u0131); video: Pexels (\xfccretsiz lisans). Hareket \xf6nerileri genel bilgilendirmedir.",11,null)
B.ame=new A.aa("Kamp ekibinle ileti\u015fime ge\xe7ti\u011fin WhatsApp hatt\u0131ndan yazabilirsin.",12.5,null)
B.amf=new A.aa("Puanlar yaln\u0131zca senin motivasyonun i\xe7in. Ba\u015fkalar\u0131yla yar\u0131\u015f yok; tek k\u0131yas d\xfcnk\xfc sen.",12,null)
B.amg=new A.aa("De\u011ferler T\xdcRKOMP verilerine yak\u0131n tahminlerdir; pi\u015firme y\xf6ntemi ve porsiyona g\xf6re de\u011fi\u015fir.",11,null)
B.ami=new A.aa("D\xf6rt kamp, d\xf6rt farkl\u0131 h\u0131z. Hepsinde ayn\u0131 ilke: yasak listesi yok, \xf6nce protein ve lif, her g\xfcn k\xfc\xe7\xfck ve yap\u0131labilir bir g\xf6rev.",14,null)
B.amj=new A.aa("1 dakika",12,null)
B.amk=new A.aa("Dyt. Cansu kontrol edip onaylad\u0131ktan sonra kesinle\u015fir.",12,null)
B.amm=new A.aa("Kaynak: USDA FoodData Central; Drouin-Chartier ve ark., BMJ 2020 (yumurta ve kardiyovask\xfcler hastal\u0131k meta-analizi).",11,null)
B.amn=new A.aa("Kilo ve \xf6l\xe7\xfcmlerini Profil > \xd6l\xe7\xfcmlerim b\xf6l\xfcm\xfcnden ayr\u0131ca girebilirsin; zorunlu de\u011fil.",12,null)
B.amo=new A.aa("Kamp i\xe7erikleri herkese ayn\u0131 genel bilgilendirmedir. Ki\u015fiye \xf6zel beslenme plan\u0131n diyetisyen onay\u0131yla ayr\u0131ca gelir.",12,null)
B.amp=new A.aa("Ki\u015fisel plan\u0131n yaln\u0131zca diyetisyen onay\u0131ndan sonra g\xf6r\xfcn\xfcr. Uygulama tan\u0131 koymaz, tedavi, ila\xe7 ya da takviye \xf6nermez.",12.5,null)
B.amq=new A.aa("\xd6rnek: 1 yumurta \u2248 6 g, 1 kase yo\u011furt \u2248 7 g, 100 g \u0131zgara tavuk \u2248 31 g, 1 kase mercimek \xe7orbas\u0131 \u2248 9 g protein.",12,null)
B.amr=new A.aa("Hangisini se\xe7ersen se\xe7, kampta kazand\u0131\u011f\u0131n al\u0131\u015fkanl\u0131klar temel olarak kal\u0131r. Bekleme yok, bask\u0131 yok; haz\u0131r oldu\u011funda.",12,null)
B.ams=new A.aa("Kaynak: Wing ve Phelan, Long-term weight loss maintenance, American Journal of Clinical Nutrition, 2005 (Ulusal Kilo Kontrol Kayd\u0131)",11.5,null)
B.amt=new A.aa("Orta boy 1 yumurta (\u224850 g)",13,null)
B.amu=new A.aa("Bu sayfada dan\u0131\u015fan yorumu, \xf6nce/sonra g\xf6rseli ya da sonu\xe7 vaadi yer almaz (Sa\u011fl\u0131k Hizmetlerinde Tan\u0131t\u0131m ve Bilgilendirme Y\xf6netmeli\u011fi).",12,null)
B.amw=new A.aa("Yakla\u015f\u0131k de\u011ferlerdir; laboratuvar \xf6l\xe7\xfcm\xfc de\u011fildir. Ki\u015fisel porsiyonun diyetisyen onayl\u0131 plan\u0131ndad\u0131r.",11.5,null)
B.amx=new A.aa("Dyt. Cansu'nun mutfa\u011f\u0131ndan \xe7ekiliyor",12,null)
B.amy=new A.aa("Her beden ve her d\xf6nem farkl\u0131. A\u015fa\u011f\u0131daki gruplar i\xe7in genel kamp yerine Dyt. Cansu'nun birebir ilgilendi\u011fi, sana \xf6zel yaz\u0131lan programlar var.",14,null)
B.amz=new A.aa("Bu ekran tan\u0131 ya da tedavi de\u011fildir. Acil bir sa\u011fl\u0131k durumunda 112\u2019yi ara.",11,null)
B.amA=new A.aa("Her g\xfcn tart\u0131lmak gerekmez. Haftada bir, ayn\u0131 g\xfcn ve saatte, sabah a\xe7 karn\u0131na \xf6l\xe7mek e\u011filimi g\xf6rmek i\xe7in yeterli.",13,null)
B.amB=new A.aa("Profilinden al\u0131nd\u0131",12,null)
B.amC=new A.aa("Tahmin et ya da besinleri kendin ekle.",13,null)
B.amD=new A.aa("A\u015fa\u011f\u0131daki porsiyonlar\u0131n her biri yakla\u015f\u0131k 6\u20138 g protein verir. Yumurta sevmiyorsan peynir, et yemiyorsan baklagil: taba\u011f\u0131n yine dengede.",13,null)
B.amE=new A.aa("Do\u011fum ay\u0131nda sana k\xfc\xe7\xfck bir s\xfcrpriz ve hat\u0131rlatma g\xf6nderebilmemiz i\xe7in. Y\u0131l\u0131n\u0131 sormuyoruz.",13,null)
B.amF=new A.aa("Plan\u0131n senin mutfa\u011f\u0131na g\xf6re haz\u0131rlan\u0131r. Y\xf6re yemeklerinle protein ve lif \xf6nerileri.",12.5,null)
B.amG=new A.aa("Uyku kalitesi",12,null)
B.amH=new A.aa("Neden kampa al\u0131nm\u0131yor? Bu d\xf6nemlerde enerji ve besin ihtiyac\u0131, ila\xe7 ve tahlil takibi ki\u015fiye \xf6zeldir. Grup program\u0131 yerine sana \xf6zel plan daha g\xfcvenlidir.",12,null)
B.amI=new A.aa("Tahlilin yaln\u0131zca diyetisyenine gider, yapay zek\xe2ya g\xf6nderilmez. Dosya telefonunda ayr\u0131ca saklanmaz.",12,null)
B.amJ=new A.aa("Tarifler \xf6rnektir; ki\u015fiye \xf6zel men\xfcn diyetisyen onay\u0131yla gelir.",12,null)
B.amK=new A.aa("1 yumurta \u2248 6 g \xb7 1 kase yo\u011furt \u2248 7 g \xb7 avu\xe7 i\xe7i tavuk \u2248 30 g. Ayr\u0131nt\u0131: Besin rehberi.",12,null)
B.amL=new A.aa("Bu b\xf6l\xfcm bilgilendirme ama\xe7l\u0131d\u0131r, hekim kontrol\xfcn\xfcn yerini tutmaz. Kanama, \u015fiddetli kusma, ba\u015f a\u011fr\u0131s\u0131 ya da g\xf6rme bulan\u0131kl\u0131\u011f\u0131nda hekimine ba\u015fvur.",12,null)
B.amM=new A.aa("Hareket videolar\u0131: Pexels lisans\u0131 (\xfccretsiz kullan\u0131m). G\xf6rseller: free-exercise-db (kamu mal\u0131).",11,null)
B.amN=new A.aa("Online g\xf6r\xfcnt\xfcl\xfc g\xf6r\xfc\u015fme ba\u011flant\u0131s\u0131 \u015fimdilik diyetisyen taraf\u0131ndan ayr\u0131ca g\xf6nderilir; uygulama i\xe7i video sonraki a\u015famada eklenecek.",12,null)
B.amP=new A.aa("Kamp i\xe7erikleri herkese ayn\u0131 genel bilgilendirmedir; kesin kilo kayb\u0131 vaadi i\xe7ermez. Ki\u015fiye \xf6zel beslenme plan\u0131n diyetisyen onay\u0131yla ayr\u0131ca gelir. Gebe ya da emziren, kronik hastal\u0131\u011f\u0131 olan, 18 ya\u015f alt\u0131 kat\u0131l\u0131mc\u0131lar kampa de\u011fil birebir programa al\u0131n\u0131r.",12,null)
B.amQ=new A.aa("Bu cihazda denerken kay\u0131tlar\u0131n yaln\u0131zca telefonunda durur, diyetisyenine gitmez. \u0130stedi\u011fin zaman Profil > Hesab\u0131m b\xf6l\xfcm\xfcnden hesap a\xe7abilirsin.",12,null)
B.amS=new A.aa("Kay\u0131tlar\u0131n \u015fu an yaln\u0131zca bu cihazda. Hesap a\xe7arsan diyetisyenin seni takip edebilir.",13,null)
B.amT=new A.aa("Olur b\xf6yle g\xfcnler. A\u015fa\u011f\u0131dakiler Dyt. Cansu'nun bu \xf6\u011f\xfcn i\xe7in onaylad\u0131\u011f\u0131, yakla\u015f\u0131k e\u015fde\u011fer se\xe7eneklerdir.",13,null)
B.amU=new A.aa("Porsiyon, etiket okuma ve tabak modeli videolar\u0131 da ayn\u0131 \u015fekilde panelden eklenecek.",13,null)
B.amV=new A.aa("Canl\u0131 yay\u0131nda ki\u015fisel sa\u011fl\u0131k bilgilerin payla\u015f\u0131lmaz. Sana \xf6zel sorular i\xe7in Dyt. Cansu'ya \xf6zelden yaz.",12,null)
B.amW=new A.aa("Bu \xf6zet genel bilgilendirme ama\xe7l\u0131d\u0131r.",12,null)
B.amX=new A.aa("Hangisini se\xe7ersen se\xe7, do\u011fru ya da yanl\u0131\u015f yok. Fark etmi\u015f olman yeterli.",13,null)
