B.aJQ=new A.fB("uyluk","Uyluk","cm","Uylu\u011fun en kal\u0131n yeri, kal\xe7a k\u0131vr\u0131m\u0131n\u0131n hemen alt\u0131.","Ayaklar omuz geni\u015fli\u011finde, a\u011f\u0131rl\u0131k iki bacakta e\u015fit. Hep ayn\u0131 baca\u011f\u0131 (sa\u011f) \xf6l\xe7.",B.vj,25,120)
